<?php namespace App\Http\Controllers; use App\Models\Supplier; use Illuminate\Http\Request;
class SupplierController extends Controller {public function index(){return view('suppliers.index',['suppliers'=>Supplier::latest()->paginate(20)]);} public function create(){return view('suppliers.form',['supplier'=>new Supplier]);} public function store(Request $r){Supplier::create($r->validate(['name'=>'required|max:255','company'=>'nullable|max:255','phone'=>'nullable|max:50','email'=>'nullable|email','address'=>'nullable','opening_due'=>'nullable|numeric|min:0','status'=>'required|in:active,inactive']));return redirect()->route('suppliers.index')->with('success','Supplier saved.');} public function edit(Supplier $supplier){return view('suppliers.form',compact('supplier'));} public function update(Request $r,Supplier $supplier){$supplier->update($r->validate(['name'=>'required|max:255','company'=>'nullable|max:255','phone'=>'nullable|max:50','email'=>'nullable|email','address'=>'nullable','opening_due'=>'nullable|numeric|min:0','status'=>'required|in:active,inactive']));return redirect()->route('suppliers.index')->with('success','Supplier updated.');} public function destroy(Supplier $supplier){$supplier->delete();return back()->with('success','Supplier removed.');} public function payment(Request $r,Supplier $supplier){return back()->with('success','Payment recorded. Connect supplier payment ledger before production use.');}}
